#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstdio>
#include <climits>
using namespace std;

using lli = long long;
const lli INF_DIST = 1000000007LL;

struct edge {
    int src;
    int dst;
    int cap;
    int flw;
    int cst;
    edge(int s, int d, int cp, int fl, int ct)
        : src(s), dst(d), cap(cp), flw(fl), cst(ct) {}
};

int N_NODES, N_EDGES, K_PLANETS, COST_C, COST_D;
int planet_arr[5005];
int SOURCE, SINK;

namespace MCMF {
    vector<edge> EL;
    vector<int> adj[500500];
    int d[500500], p[500500], a[500500];
    bool inq[500500];

    void setup(int n) {
        for (int i = 0; i <= n; ++i) {
            adj[i].clear();
        }
        EL.clear();
    }

    void add_edge(int u, int v, int cap, int cost) {
        EL.emplace_back(u, v, cap, 0, cost);
        EL.emplace_back(v, u, 0, 0, -cost);
        int m = EL.size();
        adj[u].push_back(m - 2);
        adj[v].push_back(m - 1);
    }

    bool spfa(int s, int t, int& flow, int& cost) {
        fill(d, d + t + 1, INT_MAX);
        fill(inq, inq + t + 1, false);
        d[s] = 0;
        inq[s] = true;
        a[s] = INT_MAX;
        queue<int> q;
        q.push(s);

        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = false;

            for (int idx : adj[u]) {
                edge& e = EL[idx];
                if (e.cap > e.flw && d[e.dst] > d[u] + e.cst) {
                    d[e.dst] = d[u] + e.cst;
                    p[e.dst] = idx;
                    a[e.dst] = min(a[u], e.cap - e.flw);
                    if (!inq[e.dst]) {
                        inq[e.dst] = true;
                        q.push(e.dst);
                    }
                }
            }
        }

        if (d[t] == INT_MAX) return false;
        flow += a[t];
        cost += d[t] * a[t];
        int cur = t;
        while (cur != s) {
            EL[p[cur]].flw += a[t];
            EL[p[cur] ^ 1].flw -= a[t];
            cur = EL[p[cur]].src;
        }
        return true;
    }

    int min_cost_flow(int s, int t) {
        int total_flow = 0, total_cost = 0;
        while (spfa(s, t, total_flow, total_cost));
        return total_cost;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N_NODES >> N_EDGES >> K_PLANETS >> COST_C >> COST_D;

    for (int i = 1; i <= K_PLANETS; ++i) {
        scanf("%d", &planet_arr[i]);
    }

    SOURCE = 0;
    SINK = N_NODES * 100 + 1;

    for (int i = 1; i <= K_PLANETS; ++i) {
        MCMF::add_edge(SOURCE, 1 + (planet_arr[i] - 1) * 100, 1, 0);
    }

    for (int i = 1; i <= N_NODES; ++i) {
        int base = (i - 1) * 100LL;
        for (int j = 1; j < 100; ++j) {
            MCMF::add_edge(base + j, base + j + 1, INT_MAX, COST_C);
        }
    }

    for (int i = 1; i <= 100; ++i) {
        MCMF::add_edge(i, SINK, INT_MAX, 0);
    }

    while (N_EDGES--) {
        int x, y;
        scanf("%d%d", &x, &y);
        for (int i = 1; i < 100; ++i) {
            int u = (x - 1) * 100 + i;
            int v = (y - 1) * 100 + i + 1;
            for (int j = 1; j <= 50; ++j) {
                int w = COST_D * (j * j - (j - 1) * (j - 1)) + COST_C;
                MCMF::add_edge(u, v, 1, w);
            }
        }

        for (int i = 1; i < 100; ++i) {
            int u = (y - 1) * 100 + i;
            int v = (x - 1) * 100 + i + 1;
            for (int j = 1; j <= 50; ++j) {
                int w = COST_D * (j * j - (j - 1) * (j - 1)) + COST_C;
                MCMF::add_edge(u, v, 1, w);
            }
        }
    }

    printf("%d\n", MCMF::min_cost_flow(SOURCE, SINK));
    return 0;
}
